Task prompt: You're a powerful Magician learning new spells! Implement the FireballSpell and HealSpell classes. Both should inherit from the Spell class and override its 'cast' method to perform their unique magical effects, demonstrating polymorphism in action.

Current code:
class Shape {
  area() {
    return 0;
  }
}

class Circle extends Shape {
  constructor(radius) {
    super();
    this.radius = radius;
  }

  area() {
    return Math.PI * this.radius;
  }
}

class Rectangle extends Shape {
  constructor(width, height) {
    super();
    this.width = width;
    this.height = height;
  }

  area() {
    return this.width + this.height;
  }
}

function totalArea(shapes) {
  return shapes.length;
}


