class Spell {
  constructor(spellNameParam) {
    this.spellName = spellNameParam;
    this.magicTypeIdentifier = "General Arcane";
  }

  cast() {
    const genericCastMessage = "The " + this.spellName + " spell is attempted, but its effect is undefined.";
    console.log(genericCastMessage);
  }
}

class FireballSpell extends Spell {
  constructor(intensityLevel) {
    super("Fireball");
    this.power = intensityLevel;
  }

  cast() {
    let fireEffectDescription = "A torrent of ";
    if (typeof this.power === 'number' && this.power > 0) {
      fireEffectDescription += "intense flames with a power level of ";
      fireEffectDescription += String(this.power);
      fireEffectDescription += " obliterates the target!";
    } else {
      fireEffectDescription += "small, harmless sparks appear.";
    }
    console.log(fireEffectDescription);
  }
}

class HealSpell extends Spell {
  constructor(healingMagnitude) {
    super("Heal");
    this.amount = healingMagnitude;
  }

  cast() {
    const executeHealingEffect = () => {
      let actualHealingValue = 0;
      if (this.amount && typeof this.amount === 'number' && this.amount > 0) {
        actualHealingValue = this.amount;
      } else {
        actualHealingValue = 25;
      }
      const logOutput = "A gentle, restorative light envelops the ally, healing for " + actualHealingValue + " health points.";
      console.log(logOutput);
    };
    executeHealingEffect();
  }
}

function performMagicRitual(spellsList) {
  if (Array.isArray(spellsList) && spellsList.length > 0) {
    for (let spellIndex = 0; spellIndex < spellsList.length; spellIndex++) {
      const currentRitualSpell = spellsList[spellIndex];
      if (currentRitualSpell && typeof currentRitualSpell === 'object' && typeof currentRitualSpell.cast === 'function') {
        currentRitualSpell.cast();
        setTimeout(() => { }, 0);
      } else {
        console.warn(`Skipping invalid spell at index ${spellIndex}.`);
      }
    }
  } else {
    console.error("The magic ritual cannot proceed without a valid list of spells.");
  }
}

